#include "ratings.hpp"

double expectedScore(double home, double away, double advantage) { return 1 / (1 + std::pow(10.0, (away - home - advantage) / 400)); }
EloRun runElo(int count, const Matches& matches, Integer coefficient, Integer advantage, Integer initial) {
    EloRun run; run.ratings.assign(count, initial);
    for (std::size_t index = 0; index < matches.size(); ++index) {
        const Match& match = matches[index]; double home = run.ratings[match.home], away = run.ratings[match.away];
        double expected = expectedScore(home, away, advantage), multiplier = 1;
        if (match.margin()) { double difference = match.margin() > 0 ? home + advantage - away : away - home - advantage; multiplier = std::log(std::abs(match.margin()) + 1) * 2.2 / (0.001 * difference + 2.2); }
        double change = coefficient * multiplier * (match.result() - expected);
        run.ratings[match.home] = home + change; run.ratings[match.away] = away - change;
        run.expected.push_back(expected); run.changes.push_back(change);
        if (index + 1 == matches.size() || matches[index + 1].round != match.round) run.rounds.push_back(run.ratings);
    }
    return run;
}

#include "ratings.hpp"

double sigma(double value) { return 1 / (1 + std::exp(-value)); }
std::pair<double, double> fitLink(const Values& features, const Values& results, Integer iterations) {
    double alpha = 0, beta = 0;
    for (Integer iteration = 0; iteration < iterations; ++iteration) {
        double g0 = 0, g1 = 0, h00 = 0, h01 = 0, h11 = 0;
        for (std::size_t i = 0; i < features.size(); ++i) { double z = features[i], p = sigma(alpha + beta * z), w = p * (1 - p); g0 += results[i] - p; g1 += (results[i] - p) * z; h00 += w; h01 += w * z; h11 += w * z * z; }
        double determinant = h00 * h11 - h01 * h01;
        alpha += (h11 * g0 - h01 * g1) / determinant; beta += (h00 * g1 - h01 * g0) / determinant;
    }
    return {alpha, beta};
}
double logLoss(double probability, double result) { if (result == 1) return -std::log(probability); if (result == 0) return -std::log(1 - probability); return -(std::log(probability) / 2 + std::log(1 - probability) / 2); }
double brierScore(double probability, double result) { return (probability - result) * (probability - result); }
Fraction correctness(double probability, int result) { if (result == 1) return {1, 2}; return {(probability > 0.5 && result == 2) || (probability < 0.5 && result == 0) ? 1 : 0}; }
static int direction(Fraction first, Fraction second) { return first > second ? 1 : first < second ? -1 : 0; }
Fraction kendallTau(const Fractions& first, const Fractions& second) {
    Integer balance = 0, count = static_cast<Integer>(first.size());
    for (int t = 0; t < count; ++t) for (int u = t + 1; u < count; ++u) balance += direction(first[t], first[u]) * direction(second[t], second[u]);
    return {balance, count * (count - 1) / 2};
}
static std::vector<Integer> doubledRanks(const Fractions& values) {
    std::vector<Integer> result;
    for (Fraction value : values) { Integer greater = 0, equal = 0; for (Fraction other : values) { greater += other > value; equal += other == value; } result.push_back(2 * greater + equal + 1); }
    return result;
}
Fraction spearmanRho(const Fractions& first, const Fractions& second) {
    std::vector<Integer> a = doubledRanks(first), b = doubledRanks(second); Integer sum = 0, count = static_cast<Integer>(a.size());
    for (std::size_t i = 0; i < a.size(); ++i) { Integer difference = a[i] - b[i]; sum += difference * difference; }
    return Fraction(1) - Fraction(6 * sum, 4 * count * (count * count - 1));
}

#include "ratings.hpp"

std::pair<Values, double> bradleyTerry(int count, const Matches& matches, Integer iterations) {
    Values wins(count), strengths(count, 1); double homeWins = 0, theta = 1;
    for (const Match& match : matches) { wins[match.home] += match.result(); wins[match.away] += 1 - match.result(); homeWins += match.result(); }
    for (Integer iteration = 0; iteration < iterations; ++iteration) {
        Values zeta(count);
        for (const Match& match : matches) { double denominator = theta * strengths[match.home] + strengths[match.away]; zeta[match.home] += theta / denominator; zeta[match.away] += 1 / denominator; }
        for (int i = 0; i < count; ++i) strengths[i] = wins[i] / zeta[i];
        double sum = 0; for (double strength : strengths) sum += strength;
        for (double& strength : strengths) strength = strength * count / sum;
        double denominator = 0; for (const Match& match : matches) denominator += strengths[match.home] / (theta * strengths[match.home] + strengths[match.away]);
        theta = homeWins / denominator;
    }
    return {strengths, theta};
}
OffenseDefense offenseDefense(int count, const Matches& matches, Integer iterations) {
    std::vector<Integers> points(count, Integers(count)); OffenseDefense fit{Values(count), Values(count, 1), Values(count)};
    for (const Match& match : matches) { points[match.home][match.away] += match.awayScore; points[match.away][match.home] += match.homeScore; }
    for (Integer iteration = 0; iteration < iterations; ++iteration) {
        for (int j = 0; j < count; ++j) { double sum = 0; for (int i = 0; i < count; ++i) sum += points[i][j] / fit.defense[i]; fit.offense[j] = sum; }
        for (int i = 0; i < count; ++i) { double sum = 0; for (int j = 0; j < count; ++j) sum += points[i][j] / fit.offense[j]; fit.defense[i] = sum; }
    }
    for (int i = 0; i < count; ++i) fit.ratings[i] = fit.offense[i] / fit.defense[i];
    return fit;
}

#include "ratings.hpp"

using Matrix = std::vector<Values>;
static Values choleskySolve(const Matrix& matrix, const Values& vector) {
    int count = static_cast<int>(vector.size()); Matrix lower(count, Values(count)); Values forward(count), result(count);
    for (int i = 0; i < count; ++i) for (int j = 0; j <= i; ++j) { double sum = 0; for (int k = 0; k < j; ++k) sum += lower[i][k] * lower[j][k]; lower[i][j] = i == j ? std::sqrt(matrix[i][i] - sum) : (matrix[i][j] - sum) / lower[j][j]; }
    for (int i = 0; i < count; ++i) { double sum = 0; for (int k = 0; k < i; ++k) sum += lower[i][k] * forward[k]; forward[i] = (vector[i] - sum) / lower[i][i]; }
    for (int i = count - 1; i >= 0; --i) { double sum = 0; for (int k = i + 1; k < count; ++k) sum += lower[k][i] * result[k]; result[i] = (forward[i] - sum) / lower[i][i]; }
    return result;
}
static Values gaussianSolve(Matrix matrix, Values vector) {
    int count = static_cast<int>(vector.size()); Values result(count);
    for (int k = 0; k < count; ++k) {
        int pivot = k; for (int row = k + 1; row < count; ++row) if (std::abs(matrix[row][k]) > std::abs(matrix[pivot][k])) pivot = row;
        std::swap(matrix[k], matrix[pivot]); std::swap(vector[k], vector[pivot]);
        for (int i = k + 1; i < count; ++i) { double factor = matrix[i][k] / matrix[k][k]; for (int j = k; j < count; ++j) matrix[i][j] -= factor * matrix[k][j]; vector[i] -= factor * vector[k]; }
    }
    for (int i = count - 1; i >= 0; --i) { double sum = 0; for (int j = i + 1; j < count; ++j) sum += matrix[i][j] * result[j]; result[i] = (vector[i] - sum) / matrix[i][i]; }
    return result;
}
Values colleyRatings(int count, const Matches& matches) {
    Matrix matrix(count, Values(count)); Integers balance(count); Values vector(count);
    for (int i = 0; i < count; ++i) matrix[i][i] = 2;
    for (const Match& match : matches) { int home = match.home, away = match.away; ++matrix[home][home]; ++matrix[away][away]; --matrix[home][away]; --matrix[away][home]; if (match.margin() > 0) { ++balance[home]; --balance[away]; } else if (match.margin() < 0) { --balance[home]; ++balance[away]; } }
    for (int i = 0; i < count; ++i) vector[i] = 1 + balance[i] / 2.0;
    return choleskySolve(matrix, vector);
}
std::pair<Values, double> masseyRatings(int count, const Matches& matches) {
    Matrix matrix(count + 1, Values(count + 1)); Values vector(count + 1);
    for (const Match& match : matches) {
        int home = match.home, away = match.away; ++matrix[home][home]; ++matrix[away][away]; --matrix[home][away]; --matrix[away][home]; ++matrix[home][count]; ++matrix[count][home]; --matrix[away][count]; --matrix[count][away]; ++matrix[count][count];
        vector[home] += match.margin(); vector[away] -= match.margin(); vector[count] += match.margin();
    }
    matrix[count - 1].assign(count + 1, 1); matrix[count - 1][count] = 0; vector[count - 1] = 0;
    Values solution = gaussianSolve(matrix, vector); double advantage = solution.back(); solution.pop_back(); return {solution, advantage};
}

